// brain.js: what the pet does now. Pure state, no `$`, no clock: every call takes the time.
// Inputs: what Claude is doing (activity), signals from mods and programs, emotes, slots (other mods' band rows).
// Output: pick(now) → { state, info, say, by, emote }.
// Priority: a permission prompt waiting on you (100) > signals by their priority (0–99; ties: the newest) >
// Claude working (50) > nothing (idle, or asleep after a long quiet or late at night).

import { STATES } from './pack.js'
import { EMOTES, EMOTE_MS } from './fx.js'

export const SCENES = ['idle', 'monitor', 'notes', 'confetti', 'rain', 'night', 'bell', 'ticket', 'laptop', 'dizzy']
const SCENE_STATE = { idle: 'idle', notes: 'happy', confetti: 'cheer', rain: 'sad', night: 'sleep', bell: 'alert', ticket: 'needs', laptop: 'think', dizzy: 'dizzy' }

const num = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? v : d)
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v))

/** −2…2 → the monitor's mood. */
export function moodState(m) {
  if (m >= 1.2) return 'ecstatic'
  if (m >= 0.35) return 'happy'
  if (m <= -1.2) return 'sad'
  if (m <= -0.35) return 'worried'
  return 'calm'
}

function normSpan(sp) {
  if (!Array.isArray(sp) || typeof sp[0] !== 'string') return null
  const st = sp[1] && typeof sp[1] === 'object' ? sp[1] : {}
  return [sp[0].slice(0, 400), { color: typeof st.color === 'string' ? st.color : undefined, dim: st.dim === true, bold: st.bold === true }]
}

/**
 * options: { sleepAfterMs = 20 min, nightSleepAfterMs = 3 min, nightUntilHour = 7, hourOf = (ms) => local hour }
 */
export function createBrain(options) {
  const o = { sleepAfterMs: 20 * 60e3, nightSleepAfterMs: 3 * 60e3, nightUntilHour: 7, hourOf: (ms) => new Date(ms).getHours(), ...(options || {}) }
  const signals = new Map()        // source → signal
  const slots = new Map()          // source → { rows, order, action, key }
  let emote = null                 // the latest: { kind, t0, until, say, source }
  let demoAt = 0
  let changed = false              // something the band draws changed (rows, a line of speech)
  const act = { working: false, doing: null, doingAt: 0, needs: 0, needsTool: '', lastActive: 0 }

  const brain = {
    act,
    signals,
    slots,
    /** True once after anything the band's text depends on changed. */
    takeChanged() { const c = changed; changed = false; return c },

    signal(a, at) {
      if (!a || typeof a.source !== 'string' || !a.source) return { ok: false, error: 'source: a non-empty string' }
      const source = a.source.slice(0, 64)
      if (a.scene === null) { if (signals.delete(source)) changed = true; return { ok: true } }
      if (!SCENES.includes(a.scene)) return { ok: false, error: 'scene: one of ' + SCENES.join(', ') + ', or null' }
      const rec = {
        source, scene: a.scene, mood: num(a.mood, 0),
        bars: Array.isArray(a.bars) ? a.bars.slice(0, 3).map(Number).filter(Number.isFinite) : null,
        tool: typeof a.tool === 'string' ? a.tool.slice(0, 32) : null,
        say: typeof a.say === 'string' && a.say ? a.say.slice(0, 200) : null,
        priority: clamp(Math.round(num(a.priority, 30)), 0, 99),
        until: at + clamp(num(a.ttlMs, 15 * 60e3), 1000, 24 * 3600e3),
        at,
      }
      // The same source repeating the same scene (a renewal, new bar heights) keeps its time, so two sources of one
      // priority do not take turns winning each time one of them re-sends.
      const old = signals.get(source)
      const same = old && old.until > at && old.scene === rec.scene && old.say === rec.say && old.priority === rec.priority
      if (same) rec.at = old.at
      signals.set(source, rec)
      if (!same) changed = true
      return { ok: true }
    },

    emote(a, at) {
      if (!a || !EMOTES.includes(a.emote)) return { ok: false, error: 'emote: one of ' + EMOTES.join(', ') }
      emote = { kind: a.emote, t0: at, until: at + EMOTE_MS, say: typeof a.say === 'string' && a.say ? a.say.slice(0, 200) : null, source: typeof a.source === 'string' ? a.source.slice(0, 64) : '' }
      changed = true
      return { ok: true }
    },

    slot(a) {
      if (!a || typeof a.source !== 'string' || !a.source) return { ok: false, error: 'source: a non-empty string' }
      const source = a.source.slice(0, 64)
      if (a.rows === null || a.rows === undefined) { if (slots.delete(source)) changed = true; return { ok: true } }
      if (!Array.isArray(a.rows)) return { ok: false, error: 'rows: an array of rows, or null' }
      const rows = a.rows.slice(0, 6).map((r) => (Array.isArray(r) ? r.map(normSpan).filter(Boolean) : []))
      const action = a.action && typeof a.action.label === 'string' && typeof a.action.command === 'string'
        ? { label: a.action.label.slice(0, 16), command: a.action.command.replace(/^\//, '').slice(0, 64) } : null
      const rec = { rows, order: clamp(num(a.order, 50), 0, 999), action }
      const key = JSON.stringify(rec)
      const old = slots.get(source)
      if (!old || old.key !== key) { slots.set(source, Object.assign(rec, { key })); changed = true }
      return { ok: true }
    },

    /** The slots in drawing order. */
    rows() { return [...slots.entries()].sort((a, b) => a[1].order - b[1].order || (a[0] < b[0] ? -1 : 1)) },

    /** Drops what expired. */
    sweep(now) {
      for (const [k, s] of signals) if (s.until <= now) { signals.delete(k); changed = true }
      if (emote && emote.until <= now) { if (emote.say) changed = true; emote = null }
    },

    demo(at) { demoAt = at; changed = true },

    activity: {
      tool(name, at) { act.doing = name; act.doingAt = at; act.lastActive = at },
      toolDone(name) { if (act.needs && act.needsTool === name) { act.needs = 0; changed = true } },
      permission(toolName, at) { act.needs = at || 1; act.needsTool = toolName || ''; act.lastActive = at; changed = true },
      turnStart(at) { act.working = true; act.lastActive = at },
      turnEnd(at) { act.working = false; act.doing = null; act.needs = 0; act.lastActive = at; changed = true },
      prompt(at) { act.lastActive = at },
      working(v, at) { if (v && !act.working) act.lastActive = at; act.working = !!v },
    },

    pick(now) {
      const em = emote && now < emote.until ? { kind: emote.kind, t0: emote.t0 } : null
      const emSay = emote && now < emote.until ? emote.say : null
      if (demoAt) {
        const k = Math.floor((now - demoAt) / 2500)
        if (k >= 0 && k < STATES.length) return { state: STATES[k], info: { bars: [1.1, -0.6, 0.4], tool: 'Bash' }, say: 'demo: ' + STATES[k], by: 'demo', emote: em }
        demoAt = 0
      }
      let best = null
      const consider = (c) => { if (!best || c.pr > best.pr || (c.pr === best.pr && c.at > best.at)) best = c }
      if (act.needs && now - act.needs < 10 * 60e3) consider({ state: 'needs', info: {}, pr: 100, at: act.needs, by: 'activity', say: null })
      if (act.working) consider({ state: 'think', info: { tool: act.doing && now - act.doingAt < 60e3 ? act.doing : null }, pr: 50, at: act.doingAt, by: 'activity', say: null })
      for (const s of signals.values()) {
        if (s.until <= now) continue
        const state = s.scene === 'monitor' ? moodState(s.mood) : SCENE_STATE[s.scene] || 'idle'
        consider({ state, info: { bars: s.bars, tool: s.tool }, pr: s.priority, at: s.at, by: s.source, say: s.say })
      }
      if (!best) {
        const quiet = now - act.lastActive
        const sleepy = quiet > o.sleepAfterMs || (o.hourOf(now) < o.nightUntilHour && quiet > o.nightSleepAfterMs)
        best = { state: sleepy ? 'sleep' : 'idle', info: {}, pr: 0, at: 0, by: 'activity', say: null }
      }
      return { state: best.state, info: best.info, say: emSay || best.say, by: best.by, emote: em }
    },
  }
  return brain
}

files.engine/pack.js:
// pack.js: pet packs. A pack is a pet: its size, its pixel mode and how it looks in each state.
//   code pack  { ..., render(C, t, state, info) }       ships inside the plugin (pets/), can do anything
//   data pack  { ..., palette, sprites, states }         plain JSON: a file in ~/.config/clawd/pets/, or another
//                                                        plugin's $.clawd.pack(); compiled here, never run as code
// Both compile to one shape (Pack below), which a stage draws, one frame per call. docs/PACKS.md is the format.

import { createCanvas, color, sprite as toSprite } from './pixel.js'
import { FX, EMOTE_FX, EMOTE_MS, emoteOffset } from './fx.js'
import BUILTIN from '../pets/index.js'

export const FORMAT = 'cc-clawd/pack@1'
export const STATES = ['idle', 'calm', 'happy', 'ecstatic', 'cheer', 'worried', 'sad', 'sleep', 'alert', 'needs', 'think', 'dizzy']
/** Where a state a pack lacks falls back to, step by step, ending at idle. */
export const FALLBACK = { calm: 'idle', happy: 'calm', ecstatic: 'happy', cheer: 'happy', worried: 'calm', sad: 'worried', sleep: 'idle', alert: 'idle', needs: 'alert', think: 'idle', dizzy: 'worried' }
const FX_NAMES = new Set([...Object.keys(FX), 'desk'])        // desk = monitor when there are bars, coffee otherwise
const ID = /^[a-z0-9][a-z0-9-]{0,31}$/

const isNum = (v) => typeof v === 'number' && Number.isFinite(v)
const pair = (v, d) => (Array.isArray(v) && isNum(v[0]) && isNum(v[1]) ? [Math.round(v[0]), Math.round(v[1])] : d)

/** The state a pack draws for `state`: itself if the pack has it, else down the fallback chain, else idle. */
export function resolveState(pack, state) {
  let s = state
  for (let i = 0; i < 12 && s && !pack.has(s); i++) s = (pack.fallback && pack.fallback[s]) || FALLBACK[s]
  return s && pack.has(s) ? s : 'idle'
}

function common(def, errors) {
  if (!def || typeof def !== 'object') { errors.push('a pack is an object'); return null }
  if (def.format !== FORMAT) errors.push('format must be "' + FORMAT + '"')
  if (typeof def.id !== 'string' || !ID.test(def.id)) errors.push('id: 1–32 of a–z, 0–9, "-", starting with a letter or digit')
  const cols = def.cols, rows = def.rows
  if (!Number.isInteger(cols) || cols < 4 || cols > 40) errors.push('cols: a whole number from 4 to 40')
  if (!Number.isInteger(rows) || rows < 1 || rows > 4) errors.push('rows: a whole number from 1 to 4')
  const mode = def.mode || 'quad'
  if (mode !== 'quad' && mode !== 'half') errors.push('mode: "quad" or "half"')
  const fallback = {}
  if (def.fallback != null) {
    if (typeof def.fallback !== 'object') errors.push('fallback: an object of state → state')
    else for (const [k, v] of Object.entries(def.fallback)) {
      if (!STATES.includes(k) || !STATES.includes(v)) errors.push('fallback: ' + k + ' → ' + v + ' names a state that does not exist')
      else fallback[k] = v
    }
  }
  return {
    id: String(def.id), name: typeof def.name === 'string' ? def.name.slice(0, 40) : String(def.id),
    author: typeof def.author === 'string' ? def.author.slice(0, 80) : '',
    description: typeof def.description === 'string' ? def.description.slice(0, 200) : '',
    cols, rows, mode, fallback, anchor: pair(def.anchor, [Math.max(0, (cols * (mode === 'half' ? 1 : 2)) >> 1), 0]),
    look: pair(def.look, null),                       // where the eyes are (pixels): the client turns them to the pointer
  }
}

function compileData(def, errors) {
  const base = common(def, errors)
  if (!base) return null
  const w = base.cols * (base.mode === 'half' ? 1 : 2), h = base.rows * 2
  const palette = {}
  if (!def.palette || typeof def.palette !== 'object') errors.push('palette: an object of character → colour')
  else for (const [ch, v] of Object.entries(def.palette)) {
    if (ch.length !== 1 || ch === '.' || ch === ' ') { errors.push('palette: keys are single characters other than "." and " "'); continue }
    try { palette[ch] = color(v) } catch (err) { errors.push('palette "' + ch + '": ' + err.message) }
  }
  const sprites = {}
  if (!def.sprites || typeof def.sprites !== 'object') errors.push('sprites: an object of name → rows of characters')
  else for (const [name, lines] of Object.entries(def.sprites)) {
    if (!Array.isArray(lines) || !lines.every((l) => typeof l === 'string')) { errors.push('sprite ' + name + ': rows of characters'); continue }
    if (lines.length > h || lines.some((l) => l.length > w)) errors.push('sprite ' + name + ': larger than the canvas (' + w + '×' + h + ' pixels)')
    try { sprites[name] = toSprite(lines, palette) } catch (err) { errors.push('sprite ' + name + ': ' + err.message.replace('sprite: ', '')) }
  }
  const at = pair(def.at, [0, 0])
  const states = {}
  if (!def.states || typeof def.states !== 'object') errors.push('states: an object of state → { frames, fx? }')
  else for (const [state, spec] of Object.entries(def.states)) {
    if (!STATES.includes(state)) { errors.push('states: "' + state + '" is not one of ' + STATES.join(', ')); continue }
    const frames = []
    for (const f of (spec && spec.frames) || []) {
      if (!Array.isArray(f) || typeof f[0] !== 'string' || !isNum(f[1]) || f[1] <= 0 || f[1] > 60000) { errors.push(state + ': a frame is [sprite, ms (1–60000), dx?, dy?]'); continue }
      if (!sprites[f[0]]) { errors.push(state + ': no sprite "' + f[0] + '"'); continue }
      frames.push({ sprite: sprites[f[0]], ms: f[1], dx: isNum(f[2]) ? Math.round(f[2]) : 0, dy: isNum(f[3]) ? Math.round(f[3]) : 0 })
    }
    if (!frames.length) { errors.push(state + ': needs at least one frame'); continue }
    const fx = []
    for (const e of (spec && spec.fx) || []) {
      if (!Array.isArray(e) || !FX_NAMES.has(e[0]) || !isNum(e[1]) || !isNum(e[2])) { errors.push(state + ': an effect is [name, x, y, options?], name one of ' + [...FX_NAMES].join(', ')); continue }
      fx.push({ name: e[0], x: Math.round(e[1]), y: Math.round(e[2]), opts: e[3] && typeof e[3] === 'object' ? e[3] : {} })
    }
    states[state] = { frames, fx, total: frames.reduce((n, f) => n + f.ms, 0) }
  }
  if (!states.idle && !errors.length) errors.push('states: "idle" is required (every other state falls back to it)')
  return {
    ...base,
    has: (s) => !!states[s],
    render(C, t, state, info) {
      const st = states[state] || states.idle
      let k = t % st.total, f = st.frames[0]
      for (const fr of st.frames) { if (k < fr.ms) { f = fr; break } k -= fr.ms }
      for (const e of st.fx) {
        const name = e.name === 'desk' ? (info.bars && info.bars.length ? 'monitor' : 'coffee') : e.name
        FX[name](C, t, e.x, e.y, { ...e.opts, bars: info.bars, tool: info.tool })
      }
      C.stamp(f.sprite, at[0] + f.dx + (info.dx || 0), at[1] + f.dy + (info.dy || 0), 5)
    },
  }
}

function compileCode(def, errors) {
  const base = common(def, errors)
  if (!base) return null
  const has = new Set(Array.isArray(def.states) ? def.states.filter((s) => STATES.includes(s)) : ['idle'])
  if (!has.has('idle')) errors.push('states: "idle" is required')
  return { ...base, has: (s) => has.has(s), render: (C, t, state, info) => def.render(C, t, state, info) }
}

/**
 * A pack definition → { pack, errors }. A definition with a render function is a code pack (built-ins only:
 * functions do not cross plugins or files); anything else is a data pack. `pack` is null when there are errors.
 * The compiled pack keeps its definition as `def`, so a data pack can be handed to a Client as plain props.
 */
export function compile(def, source) {
  const errors = []
  let pack = null
  try {
    pack = def && typeof def.render === 'function' ? compileCode(def, errors) : compileData(def, errors)
  } catch (err) {
    errors.push(String(err && err.message ? err.message : err))
  }
  if (errors.length || !pack) return { pack: null, errors: errors.slice(0, 12) }
  return { pack: { ...pack, source: source || 'builtin', def: typeof def.render === 'function' ? null : def }, errors: [] }
}

/** The built-in packs, compiled once. */
export const BUILTINS = new Map()
for (const def of BUILTIN) {
  const { pack, errors } = compile(def, 'builtin')
  if (pack) BUILTINS.set(pack.id, pack)
  else throw new Error('built-in pack ' + def.id + ': ' + errors.join('; '))
}

/**
 * A stage draws one pack: draw(t, view) clears its canvas, has the pack draw `view.state` (resolved through the
 * fallbacks) with `view.info`, then lays an active emote over it. view: { state, info?, emote?: { kind, t0 } }.
 * Read the frame off `stage.canvas`: cells() for a Raster, spans() for text, rgba() for an Image.
 */
export function createStage(pack) {
  const C = createCanvas(pack.cols, pack.rows, pack.mode)
  return {
    pack,
    canvas: C,
    draw(t, view) {
      C.clear()
      const info = { ...(view.info || {}) }
      const em = view.emote && t - view.emote.t0 >= 0 && t - view.emote.t0 < EMOTE_MS ? view.emote : null
      if (em) { const o = emoteOffset(em.kind, t - em.t0); info.dx = o.dx; info.dy = o.dy }
      pack.render(C, t, resolveState(pack, view.state), info)
      if (em && EMOTE_FX[em.kind]) FX[EMOTE_FX[em.kind]](C, t - em.t0, pack.anchor[0], pack.anchor[1])
      return C
    },
  }
}

files.engine/pixel.js:
// pixel.js: a small pixel engine for terminal cells.
// Pure, dependency-free and `$`-free: the same file runs in a Claude Code hooks module, in a Client
// surface module and in Node (tools/preview.mjs).
//
// A canvas is a grid of character cells. Each cell holds 2×2 pixels in "quad" mode (quadrant blocks ▖▗▘▝▚▞▙▛▜▟)
// or 1×2 pixels in "half" mode (half blocks ▀▄). Pixels carry a colour and a layer (z); glyphs (text, bar levels)
// can be put in whole cells over the pixels. A frame is then encoded for whichever backend draws it:
//   cells()  a Raster's `cells`: base64 of little-endian u32 [codePoint, fg, bg] triplets   terminal
//   spans()  per-row runs of [text, fg, bg]                                                Text, Client
//   rgba()   RGBA bytes, cw×ch image pixels per cell                                       Image (kitty, Ghostty)
//
// Measured on Claude Code 2.1.289 (docs/ENGINE.md): a Raster cell must be one printable, width-1 BMP character;
// the terminal paints colours at 4 bits per channel and keeps 1024 (fg, bg) pairs at once, so cells() quantizes;
// a cell has one foreground and one background, so when a cell's pixels disagree the highest layer wins there.
// rgba() has no such limits: every pixel keeps its own colour.

import { glyphBits } from './font.js'

export const PIXEL_VERSION = '2.0.0'
export const DEF = 0x01000000                         // "the terminal's own colour"

const QUAD = [' ', '▗', '▖', '▄', '▝', '▐', '▞', '▟', '▘', '▚', '▌', '▙', '▀', '▜', '▛', '█'].map((c) => c.codePointAt(0))
const UPPER = 0x2580, LOWER = 0x2584, FULL = 0x2588, SPACE = 0x20
/** Eighth-height bars ▁…█, for level meters. */
export const BARS = ['▁', '▂', '▃', '▄', '▅', '▆', '▇', '█'].map((c) => c.codePointAt(0))

/** 0xRRGGBB → 4 bits per channel, what the terminal actually paints. DEF passes through. */
export function q4(c) {
  if (c === DEF) return DEF
  const r = Math.round(((c >> 16) & 255) / 17) * 17
  const g = Math.round(((c >> 8) & 255) / 17) * 17
  const b = Math.round((c & 255) / 17) * 17
  return (r << 16) | (g << 8) | b
}

/** Linear blend of two 0xRRGGBB colours, k in [0, 1]. */
export function mix(a, b, k) {
  k = k < 0 ? 0 : k > 1 ? 1 : k
  const r = ((a >> 16) & 255) + (((b >> 16) & 255) - ((a >> 16) & 255)) * k
  const g = ((a >> 8) & 255) + (((b >> 8) & 255) - ((a >> 8) & 255)) * k
  const bl = (a & 255) + ((b & 255) - (a & 255)) * k
  return (Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(bl)
}

/** 0xRRGGBB → '#rrggbb'. */
export const hex = (c) => '#' + (c & 0xffffff).toString(16).padStart(6, '0')

/** '#rgb', '#rrggbb' or a number → 0xRRGGBB; throws on anything else. */
export function color(v) {
  if (typeof v === 'number' && Number.isInteger(v) && v >= 0 && v <= 0xffffff) return v
  if (typeof v === 'string') {
    const m = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(v.trim())
    if (m) {
      const s = m[1].length === 3 ? m[1].split('').map((ch) => ch + ch).join('') : m[1]
      return parseInt(s, 16)
    }
  }
  throw new Error('not a colour: ' + JSON.stringify(v))
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
/** Standard padded base64 (the engine's toBase64 when it has one). */
export function base64(u8) {
  if (typeof u8.toBase64 === 'function') return u8.toBase64()
  let s = ''
  for (let i = 0; i < u8.length; i += 3) {
    const n = (u8[i] << 16) | ((u8[i + 1] || 0) << 8) | (u8[i + 2] || 0)
    s += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + (i + 1 < u8.length ? B64[(n >> 6) & 63] : '=') + (i + 2 < u8.length ? B64[n & 63] : '=')
  }
  return s
}

/**
 * Character-art sprite: one string per row; '.' or ' ' is transparent, any other character is looked up in
 * `palette` (a 0xRRGGBB number or '#rrggbb'). Returns [dx, dy, colour] triplets for canvas.stamp().
 */
export function sprite(lines, palette) {
  const out = []
  lines.forEach((line, dy) => {
    for (let dx = 0; dx < line.length; dx++) {
      const ch = line[dx]
      if (ch === '.' || ch === ' ') continue
      if (palette[ch] === undefined) throw new Error('sprite: the palette has no "' + ch + '"')
      out.push([dx, dy, color(palette[ch])])
    }
  })
  return out
}

/** How many terminal cells a string takes (CJK and full-width are 2). */
export function cells(s) {
  let n = 0
  for (const ch of String(s)) {
    const c = ch.codePointAt(0)
    n += (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
      (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) || (c >= 0xffe0 && c <= 0xffe6) ? 2 : 1
  }
  return n
}

/**
 * A canvas of `cols`×`rows` cells: (2·cols)×(2·rows) pixels in 'quad' mode, cols×(2·rows) in 'half' mode.
 * Buffers are allocated once and reused every frame.
 *   px(x, y, colour, z)      one pixel; a higher z draws over a lower one (default 1)
 *   rect(x0, y0, x1, y1, c, z)
 *   bg(x0, y0, x1, y1, c)    background colour behind a cell's pixels (per pixel; a cell takes its first)
 *   glyph(cx, cy, ch, c)     a character in a whole cell, over the pixels (text, BARS levels)
 *   stamp(sprite, x, y, z)
 *   cellX(x), cellY(y)       which cell a pixel coordinate falls in
 *   mem                      a scratch object effects may keep state in (one per canvas)
 */
export function createCanvas(cols, rows, mode = 'quad') {
  if (mode !== 'quad' && mode !== 'half') throw new Error('mode must be quad or half')
  const sx = mode === 'half' ? 1 : 2, sy = 2
  const w = cols * sx, h = rows * sy
  const fgC = new Uint32Array(w * h), fgZ = new Uint8Array(w * h)
  const bgC = new Uint32Array(w * h), bgOn = new Uint8Array(w * h)
  const gCode = new Uint32Array(cols * rows), gFg = new Uint32Array(cols * rows)
  const words = new Uint32Array(cols * rows * 3)
  const bytes = new Uint8Array(words.buffer)
  const ids = [0, 0, 0, 0]
  let fresh = false

  function encodeQuad() {
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        const ci = cy * cols + cx, o = ci * 3
        ids[0] = (cy * 2) * w + cx * 2; ids[1] = ids[0] + 1; ids[2] = ids[0] + w; ids[3] = ids[2] + 1
        let bg = DEF
        for (let k = 0; k < 4; k++) if (bgOn[ids[k]]) { bg = q4(bgC[ids[k]]); break }
        if (gCode[ci]) { words[o] = gCode[ci]; words[o + 1] = q4(gFg[ci]); words[o + 2] = bg; continue }
        let top = 0, col = 0
        for (let k = 0; k < 4; k++) if (fgZ[ids[k]] > top) { top = fgZ[ids[k]]; col = fgC[ids[k]] }
        let bits = 0
        if (top) for (let k = 0; k < 4; k++) if (fgZ[ids[k]] && fgC[ids[k]] === col) bits |= 8 >> k
        words[o] = QUAD[bits]
        words[o + 1] = bits ? q4(col) : DEF
        words[o + 2] = bg
      }
    }
  }

  function encodeHalf() {
    for (let cy = 0; cy < rows; cy++) {
      for (let cx = 0; cx < cols; cx++) {
        const ci = cy * cols + cx, o = ci * 3
        const t = (cy * 2) * w + cx, b = t + w
        const bgT = bgOn[t] ? q4(bgC[t]) : DEF, bgB = bgOn[b] ? q4(bgC[b]) : DEF
        if (gCode[ci]) { words[o] = gCode[ci]; words[o + 1] = q4(gFg[ci]); words[o + 2] = bgT !== DEF ? bgT : bgB; continue }
        const tz = fgZ[t], bz = fgZ[b]
        if (!tz && !bz) { words[o] = SPACE; words[o + 1] = DEF; words[o + 2] = bgT !== DEF ? bgT : bgB }
        else if (tz && !bz) { words[o] = UPPER; words[o + 1] = q4(fgC[t]); words[o + 2] = bgB }
        else if (!tz && bz) { words[o] = LOWER; words[o + 1] = q4(fgC[b]); words[o + 2] = bgT }
        else {
          const a = q4(fgC[t]), d = q4(fgC[b])
          if (a === d) { words[o] = FULL; words[o + 1] = a; words[o + 2] = DEF }
          else { words[o] = UPPER; words[o + 1] = a; words[o + 2] = d }
        }
      }
    }
  }

  const c = {
    cols, rows, mode, w, h, sx, sy,
    mem: {},
    cellX: (x) => Math.floor(x / sx),
    cellY: (y) => Math.floor(y / sy),
    clear() { fgZ.fill(0); bgOn.fill(0); gCode.fill(0); fresh = false },
    px(x, y, col, z) {
      x = Math.round(x); y = Math.round(y)
      if (x < 0 || y < 0 || x >= w || y >= h) return
      const i = y * w + x, zz = z || 1
      if (zz >= fgZ[i]) { fgC[i] = col; fgZ[i] = zz; fresh = false }
    },
    rect(x0, y0, x1, y1, col, z) { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) c.px(x, y, col, z) },
    bg(x0, y0, x1, y1, col) {
      for (let y = Math.max(0, y0); y <= Math.min(h - 1, y1); y++) {
        for (let x = Math.max(0, x0); x <= Math.min(w - 1, x1); x++) { bgC[y * w + x] = col; bgOn[y * w + x] = 1 }
      }
      fresh = false
    },
    glyph(cx, cy, ch, col) {
      if (cx < 0 || cy < 0 || cx >= cols || cy >= rows) return
      gCode[cy * cols + cx] = typeof ch === 'number' ? ch : ch.codePointAt(0)
      gFg[cy * cols + cx] = col
      fresh = false
    },
    stamp(spr, x, y, z) { for (let k = 0; k < spr.length; k++) c.px(x + spr[k][0], y + spr[k][1], spr[k][2], z) },

    /** The frame as [codePoint, fg, bg] words (quantized). Reused buffer: copy it to keep it. */
    words() {
      if (!fresh) { if (mode === 'half') encodeHalf(); else encodeQuad(); fresh = true }
      return words
    },
    /** A Raster's `cells`. */
    cells() { return base64(new Uint8Array(c.words().buffer)) },
    /** Per-row runs [text, fg, bg] of equal colours; a blank cell's foreground counts as DEF. */
    spans() {
      const wd = c.words(), out = []
      for (let cy = 0; cy < rows; cy++) {
        const row = []
        let text = '', fg = -1, bg = -1
        for (let cx = 0; cx < cols; cx++) {
          const o = (cy * cols + cx) * 3
          const cp = wd[o], f = cp === SPACE ? DEF : wd[o + 1], b = wd[o + 2]
          if (f !== fg || b !== bg) { if (text) row.push([text, fg, bg]); text = ''; fg = f; bg = b }
          text += String.fromCodePoint(cp)
        }
        if (text) row.push([text, fg, bg])
        out.push(row)
      }
      return out
    },
    /** Each row's characters (tests, debugging). */
    text() {
      const wd = c.words(), out = []
      for (let cy = 0; cy < rows; cy++) {
        let s = ''
        for (let cx = 0; cx < cols; cx++) s += String.fromCodePoint(wd[(cy * cols + cx) * 3])
        out.push(s)
      }
      return out
    },
    /**
     * The frame as RGBA bytes, cw×ch image pixels per cell (default 8×16, a typical cell), unquantized: every
     * pixel its own colour, glyphs drawn from a small pixel font, transparency where nothing is drawn.
     */
    rgba(cw = 8, ch = 16) {
      const W = cols * cw, H = rows * ch
      const out = new Uint8Array(W * H * 4)
      const put = (x, y, col) => { const i = (y * W + x) * 4; out[i] = (col >> 16) & 255; out[i + 1] = (col >> 8) & 255; out[i + 2] = col & 255; out[i + 3] = 255 }
      const box = (x0, y0, bw, bh, col) => { for (let y = y0; y < y0 + bh; y++) for (let x = x0; x < x0 + bw; x++) put(x, y, col) }
      const pw = cw / sx, ph = ch / sy
      for (let cy = 0; cy < rows; cy++) {
        for (let cx = 0; cx < cols; cx++) {
          const ci = cy * cols + cx
          const X = cx * cw, Y = cy * ch
          if (gCode[ci]) {
            const p0 = (cy * sy) * w + cx * sx
            if (bgOn[p0]) box(X, Y, cw, ch, bgC[p0])
            const code = gCode[ci], col = gFg[ci]
            if (code >= 0x2581 && code <= 0x2588) { const n = Math.round(((code - 0x2580) / 8) * ch); box(X, Y + ch - n, cw, n, col); continue }
            const bits = glyphBits(code)
            const s = Math.max(1, Math.floor(Math.min(cw / 4, ch / 7)))
            const gx = X + Math.floor((cw - 3 * s) / 2), gy = Y + Math.floor((ch - 5 * s) / 2)
            for (let r = 0; r < 5; r++) for (let q = 0; q < 3; q++) if (bits[r] & (4 >> q)) box(gx + q * s, gy + r * s, s, s, col)
            continue
          }
          for (let py = 0; py < sy; py++) {
            for (let px = 0; px < sx; px++) {
              const i = (cy * sy + py) * w + cx * sx + px
              const col = fgZ[i] ? fgC[i] : bgOn[i] ? bgC[i] : -1
              if (col >= 0) box(Math.round(X + px * pw), Math.round(Y + py * ph), Math.round(pw), Math.round(ph), col)
            }
          }
        }
      }
      return { data: out, width: W, height: H }
    },
  }
  c.encode = c.cells                                         // v1 name
  return c
}

files.engine/fx.js:
// fx.js: props and effects any pet can place, each a pure function of time.
// Every effect draws relative to an origin (x, y) in pixels, the top-left of its region, so a pet of any size puts
// it where it fits; glyph positions follow from the canvas's cellX/cellY, so quad and half canvases both work.
// Natural sizes (pixels, quad mode) are in FX_SIZES; data packs (pack.js) name effects from FX.
//   fx(C, t, x, y, o)   C a canvas (pixel.js), t milliseconds, o the effect's options

import { mix, sprite, BARS } from './pixel.js'

export const PAL = {
  orange: 0xd97757, orangeHi: 0xeb8a69, orangeDim: 0x9c5a44, gray: 0x8b929c, grayDark: 0x4a4f57, screen: 0x1b2420, glow: 0x2f4a3c,
  green: 0x5cc27a, red: 0xe5605a, yellow: 0xf2c14e, cyan: 0x5cc8e8, blue: 0x6f9cf5, pink: 0xf28bb3, purple: 0xb48ee0,
  white: 0xeeeeee, moon: 0xf3e3a1, paper: 0xf1ead8, ink: 0x3a3a3a, cloud: 0x9aa3ad, mug: 0xd9d4cc, coffee: 0x6b4a2f,
}

const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v)

// A screen's sweeping glow: five cells from x+4, pixel rows y+2..y+3.
function glow(C, t, x, y, period) {
  const s = ((t / period) % 1) * 7 - 1
  const c0 = C.cellX(x + 4)
  for (let k = 0; k < 5; k++) {
    const p = (c0 + k) * C.sx
    C.bg(p, y + 2, p + C.sx - 1, y + 3, mix(PAL.screen, PAL.glow, Math.max(0, 1 - Math.abs(k - s) / 1.2) * 0.9))
  }
}

/** A monitor whose three bars show o.bars (percent; ±2 fills a bar; green up, red down), eased over ~200 ms. */
function monitor(C, t, x, y, o) {
  const g = PAL.gray
  C.rect(x + 3, y + 1, x + 14, y + 1, g, 2); C.rect(x + 3, y + 4, x + 14, y + 4, g, 2)
  for (const r of [2, 3]) { C.px(x + 3, y + r, g, 2); C.px(x + 14, y + r, g, 2) }
  C.px(x + 8, y + 5, g, 2); C.px(x + 9, y + 5, g, 2)
  glow(C, t, x, y, 2600)
  const m = C.mem.monitor || (C.mem.monitor = { shown: [0, 0, 0], t: -1 })
  const dt = m.t < 0 ? 16.7 : clamp(t - m.t, 0, 500)
  m.t = t
  const k = 1 - Math.exp(-dt / 200)
  const bars = (o && o.bars) || []
  ;[x + 4, x + 8, x + 12].forEach((bx, i) => {
    const v = bars[i] || 0
    m.shown[i] += (v - m.shown[i]) * k
    const s = m.shown[i]
    const wiggle = Math.sin(t / 230 + i * 1.9) > 0.92 ? 1 : 0
    const lvl = clamp(Math.round((Math.abs(s) / 2) * 7) + wiggle, 0, 7)
    C.glyph(C.cellX(bx), C.cellY(y + 2), BARS[lvl], Math.abs(s) < 0.03 ? PAL.grayDark : s > 0 ? PAL.green : PAL.red)
  })
  C.glyph(C.cellX(x + 10), C.cellY(y + 2), '.', mix(PAL.screen, PAL.cyan, (Math.sin(t / 160) + 1) / 2))
}

const MUG = sprite(['mmmmm.', 'mcccmh', 'mmmmmh', '.mmm..'], { m: PAL.mug, c: PAL.coffee, h: PAL.mug })
/** A steaming mug. */
function coffee(C, t, x, y) {
  C.stamp(MUG, x + 6, y + 2, 2)
  for (let i = 0; i < 2; i++) {
    const k = ((t / 1500) + i / 2) % 1
    C.px(x + 7 + i * 2 + Math.round(Math.sin(t / 300 + i * 2) * 0.6), y + 1 - k * 2.2, mix(PAL.gray, PAL.grayDark, k), 2)
  }
}

/** Falling confetti over a w×h region (default 16×6), o.n pieces. */
function confetti(C, t, x, y, o) {
  const n = (o && o.n) || 12, w = (o && o.w) || 16, h = (o && o.h) || 6
  const colors = [PAL.yellow, PAL.pink, PAL.cyan, PAL.green, PAL.purple, PAL.white]
  for (let i = 0; i < n; i++) {
    const speed = 2.6 + (i % 5) * 0.8
    C.px(x + ((i * 7) % w) + Math.sin(t / 280 + i) * 0.7, y + (((t / 1000) * speed + i * 0.83) % (h + 1)) - 1, colors[i % colors.length], 3)
  }
}

/** A cloud with rain. */
function rain(C, t, x, y) {
  C.rect(x + 4, y + 1, x + 13, y + 1, PAL.cloud, 2)
  for (const dx of [5, 6, 7, 9, 10, 11, 12]) C.px(x + dx, y, PAL.cloud, 2)
  for (let i = 0; i < 7; i++) C.px(x + 4 + ((i * 3) % 10), y + 2 + (((t / 1000) * 7 + i * 0.57) % 4), PAL.blue, 3)
}

/** Moon, twinkling stars, and z's drifting up from cell (o.zx, o.zy), default the region's first cell, row +2. */
function night(C, t, x, y, o) {
  for (const [dy, dx] of [[0, 12], [0, 13], [1, 11], [2, 11], [3, 12], [3, 13]]) C.px(x + dx, y + dy, PAL.moon, 2)
  for (const [dx, dy, k] of [[5, 0, 0], [8, 3, 1.7], [15, 1, 3.1], [3, 4, 4.4]]) C.px(x + dx, y + dy, mix(PAL.grayDark, PAL.white, (Math.sin(t / 520 + k) + 1) / 2), 2)
  zzz(C, t, x, y, o)
}

/** z's drifting up and to the right, fading. */
function zzz(C, t, x, y, o) {
  const zx = o && o.zx != null ? o.zx : C.cellX(x), zy = o && o.zy != null ? o.zy : C.cellY(y) + 2
  for (let i = 0; i < 3; i++) {
    const k = ((t / 2600) + i / 3) % 1
    C.glyph(zx + Math.floor(k * 3.2), zy - Math.floor(k * 3), k < 0.5 ? 'z' : 'Z', mix(PAL.gray, PAL.grayDark, k))
  }
}

const BELL = sprite(['..yy..', '.yyyy.', '.yyyy.', 'yyyyyy'], { y: PAL.yellow })
/** A ringing bell; '!' blinks at cell (o.bx, o.by), default the region's first cell. */
function bell(C, t, x, y, o) {
  const s = Math.round(Math.sin((t / 1000) * Math.PI * 2 * 2.2) * 1.2)
  C.stamp(BELL, x + 6 + s, y, 3)
  if (Math.floor(t / 90) % 2) for (const [dx, dy] of [[2, 1], [3, 1], [2, 2]]) C.px(x + 6 + s + dx, y + dy, 0xfff1b8, 4)
  C.px(x + 9 - s, y + 4, PAL.orangeDim, 3)
  if (s !== 0) { C.px(x + (s > 0 ? 13 : 4), y + 1, PAL.gray, 2); C.px(x + (s > 0 ? 14 : 3), y + 2, PAL.gray, 2) }
  if (Math.floor(t / 250) % 2 === 0) C.glyph(o && o.bx != null ? o.bx : C.cellX(x), o && o.by != null ? o.by : C.cellY(y), '!', PAL.yellow)
}

/** A ticket with a blinking '?': waiting for the person. */
function ticket(C, t, x, y) {
  for (let r = 0; r <= 5; r++) {
    for (let px = x + 4; px <= x + 13; px++) {
      if ((r === 0 || r === 5) && (px === x + 4 || px === x + 13)) continue
      C.px(px, y + r, mix(PAL.paper, 0xfffaf0, (Math.sin(t / 300 + px * 0.4) + 1) / 4), 2)
    }
  }
  C.glyph(C.cellX(x + 8), C.cellY(y + 2), '?', mix(PAL.paper, PAL.red, (Math.sin(t / 180) + 1) / 2))
  C.bg(x + 8, y + 2, x + 9, y + 3, PAL.paper)
}

export const SCREEN = { Read: '[==]', Grep: '?...', Glob: '?...', Edit: '+-~ ', Write: '+-~ ', NotebookEdit: '+-~ ', Bash: '>ls_', WebSearch: '@...', WebFetch: '@...', Agent: '&...', Task: '&...' }
/** A laptop whose screen types what o.tool is doing. */
function laptop(C, t, x, y, o) {
  const g = PAL.gray
  C.rect(x + 4, y + 1, x + 13, y + 1, g, 2); C.px(x + 3, y + 1, g, 2); C.px(x + 14, y + 1, g, 2)
  for (const r of [2, 3]) { C.px(x + 3, y + r, g, 2); C.px(x + 14, y + r, g, 2) }
  C.rect(x + 1, y + 4, x + 15, y + 4, g, 2)
  glow(C, t, x, y, 1800)
  const text = SCREEN[o && o.tool] || '... '
  const n = 1 + (Math.floor(t / 170) % 5)
  for (let i = 0; i < 4; i++) {
    let ch = i < n ? text[i] : ' '
    if (i === n && Math.floor(t / 350) % 2 === 0) ch = '_'
    if (ch !== ' ') C.glyph(C.cellX(x + 4) + i, C.cellY(y + 2), ch, i === 0 ? PAL.cyan : PAL.green)
  }
}

/** Stars circling, with an 'x' in the middle: dizzy. */
function orbit(C, t, x, y) {
  for (let i = 0; i < 3; i++) {
    const a = (t / 1100) * Math.PI * 2 + (i * Math.PI * 2) / 3
    C.px(x + 8.5 + Math.cos(a) * 5, y + 2.5 + Math.sin(a) * 2.4, PAL.yellow, 3)
  }
  C.glyph(C.cellX(x + 8), C.cellY(y + 2), 'x', PAL.red)
}

/** A falling drop of sweat. */
function sweat(C, t, x, y) {
  const k = (t % 1400) / 1400
  if (k < 0.85) C.px(x, y + 1 + k * 4.5, PAL.cyan, 3)
}

/** Two notes floating up. */
function notes(C, t, x, y) {
  for (let i = 0; i < 2; i++) {
    const k = ((t / 1800) + i / 2) % 1
    const px = x + i * 3 + Math.round(Math.sin(k * 6) * 0.6), py = y + 5 - k * 6
    C.px(px, py, PAL.green, 3); C.px(px + 1, py - 1, PAL.green, 3); C.px(px + 1, py - 2, PAL.green, 3)
  }
}

// ---------- emote overlays: t is the time since the emote began ----------
const HEART = sprite(['.r.r.', 'rrrrr', '.rrr.', '..r..'], { r: PAL.pink })
/** A heart rising from (x, y), fading out after a second. */
function heart(C, t, x, y) {
  if (t > 1300) return
  C.stamp(HEART, x - 2, y - Math.round((t / 1300) * 3), 6)
}
/** Three twinkles around (x, y). */
function sparkle(C, t, x, y) {
  for (const [dx, dy, k] of [[-3, 0, 0], [2, -1, 1.3], [4, 2, 2.6]]) if (Math.sin(t / 90 + k) > 0) C.px(x + dx, y + dy, PAL.yellow, 6)
}
/** A blinking '!' in the cell over (x, y). */
function bang(C, t, x, y) {
  if (Math.floor(t / 160) % 2 === 0) C.glyph(C.cellX(x), C.cellY(y), '!', PAL.yellow)
}
/** A '?' in the cell over (x, y). */
function question(C, t, x, y) {
  C.glyph(C.cellX(x), C.cellY(y), '?', PAL.cyan)
}

export const FX = { monitor, coffee, confetti, rain, night, zzz, bell, ticket, laptop, orbit, sweat, notes, heart, sparkle, bang, question }

/** Each effect's natural size in pixels (quad mode), for placing it. */
export const FX_SIZES = {
  monitor: [16, 6], coffee: [16, 6], confetti: [16, 6], rain: [16, 6], night: [16, 6], zzz: [8, 6], bell: [16, 6], ticket: [16, 6],
  laptop: [16, 6], orbit: [16, 6], sweat: [1, 6], notes: [5, 6], heart: [5, 4], sparkle: [8, 4], bang: [2, 2], question: [2, 2],
}

/** Body motion of the emotes that move the pet: an offset {dx, dy} at time t since the emote began. */
export function emoteOffset(kind, t) {
  switch (kind) {
    case 'jump': return { dx: 0, dy: t < 700 && (t % 350) < 160 ? -1 : 0 }
    case 'nod': return { dx: 0, dy: (t % 450) > 120 && (t % 450) < 260 && t < 900 ? 1 : 0 }
    case 'shake': return { dx: t < 600 ? (Math.floor(t / 60) % 2 ? 1 : -1) : 0, dy: 0 }
    default: return { dx: 0, dy: 0 }
  }
}

/** The overlay an emote draws over the pet, at the pack's anchor. */
export const EMOTE_FX = { heart: 'heart', sparkle: 'sparkle', surprise: 'bang', question: 'question', jump: null, nod: null, shake: null }
export const EMOTES = Object.keys(EMOTE_FX)
export const EMOTE_MS = 1300

